function rp_reply(array $data,int $status=200):void{http_response_code($status);echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
function rp_body():array{$raw=file_get_contents('php://input');$data=json_decode((string)$raw,true);return is_array($data)?$data:$_POST;}
function rp_num($value):float{return is_numeric($value)?(float)$value:0.0;}
function rp_money(float $value,int $decimals=8):string{return number_format(round($value,$decimals),$decimals,'.','');}
function rp_user():array{$u=current_user();return['id'=>(int)($u['id']??0),'name'=>(string)($u['name']??$u['full_name']??'Owner')];}
function rp_table_exists(PDO $pdo,string $table):bool{$st=$pdo->prepare('SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$st->execute([$table]);return(int)$st->fetchColumn()>0;}
function rp_settings(PDO $pdo):array{$out=[];foreach($pdo->query('SELECT setting_key,setting_value FROM cw_settings')->fetchAll()as$row)$out[(string)$row['setting_key']]=$row['setting_value'];return$out;}
function rp_normalize(string $value):string{return strtolower((string)preg_replace('/[^a-z0-9]+/','',strtolower($value)));}
function rp_latest_snapshot_id(PDO $pdo):int{return(int)($pdo->query("SELECT id FROM cw_sync_batches WHERE is_successful_snapshot=1 AND status='completed' ORDER BY completed_at DESC,id DESC LIMIT 1")->fetchColumn()?:0);}
function rp_calculation(array $product,array $size,?array $setup,float $selling,float $vatRate):array{
    $baseValue=rp_num($size['base_value']??1);if($baseValue<=0)$baseValue=1;
    $landed=rp_num($product['landed_cost_per_base']??0);$packEx=rp_num($setup['cost_ex_vat']??0);$packInc=rp_num($setup['cost_inc_vat']??0);
    $factor=1+max(0,$vatRate)/100;$productCost=$landed*$baseValue;$costEx=$productCost+$packEx;$costInc=($productCost*$factor)+$packInc;$priceEx=$factor>0?$selling/$factor:$selling;$profit=$priceEx-$costEx;
    return['landed_cost_per_base'=>$landed,'conversion_base_value'=>$baseValue,'product_cost_per_unit'=>$productCost,'packaging_cost_ex_vat'=>$packEx,'packaging_cost_inc_vat'=>$packInc,'total_cost_ex_vat'=>$costEx,'total_cost_inc_vat'=>$costInc,'selling_price_inc_vat'=>$selling,'selling_price_ex_vat'=>$priceEx,'profit_per_unit'=>$profit,'markup_percent'=>$costEx>0?$profit/$costEx*100:0,'margin_percent'=>$priceEx>0?$profit/$priceEx*100:0,'vat_rate'=>$vatRate];
}
function rp_sources(PDO $pdo):array{
    $products=$pdo->query("SELECT p.*,c.id landed_cost_id,c.landed_cost_per_base,c.cost_date,c.status_key landed_status FROM cw_cost_products p JOIN cw_landed_product_costs c ON c.product_id=p.id WHERE p.active=1 AND c.id=(SELECT c2.id FROM cw_landed_product_costs c2 WHERE c2.product_id=p.id ORDER BY c2.cost_date DESC,c2.id DESC LIMIT 1) ORDER BY p.product_name")->fetchAll();
    $sizes=$pdo->query("SELECT id,label,measurement_type,quantity,unit,base_value,base_unit FROM cw_size_conversions WHERE active=1 ORDER BY measurement_type,base_value")->fetchAll();
    $setups=array_values(array_filter(cw_packaging_current_setups($pdo,(new DateTimeImmutable('now',new DateTimeZone('Africa/Windhoek')))->format('Y-m-d')),function($s){return $s['complete'];}));
    $batch=rp_latest_snapshot_id($pdo);$website=[];$lastSync=null;if($batch){$st=$pdo->prepare("SELECT product_id,variation_id,parent_product_id,product_name,variation_name,sku,category,product_type,attributes,regular_price_inc_vat,sale_price_inc_vat,active_price_inc_vat,stock_quantity,stock_status,manage_stock,website_status,permalink,synced_at FROM cw_product_snapshots WHERE sync_batch_id=? ORDER BY product_name,variation_id");$st->execute([$batch]);$website=$st->fetchAll();$st=$pdo->prepare('SELECT completed_at FROM cw_sync_batches WHERE id=?');$st->execute([$batch]);$lastSync=$st->fetchColumn()?:null;}
    return compact('products','sizes','setups','website','batch','lastSync');
}
function rp_setup_applies(array $setup,array $product):bool{
    if(($setup['scope_type']??'')==='default')return true;if(($setup['scope_type']??'')==='category')return strcasecmp(trim((string)$setup['scope_label']),trim((string)$product['product_category']))===0;
    $ref=(string)($setup['scope_reference']??'');return($ref!==''&&($ref===(string)$product['id']||$ref===(string)($product['woo_product_id']??'')))||strcasecmp(trim((string)$setup['scope_label']),trim((string)$product['product_name']))===0;
}
function rp_match_size(array $site,array $sizes,array $product):?array{
    if(in_array((string)$product['costing_basis'],['count','ready_made'],true))return['id'=>0,'label'=>'1 unit','measurement_type'=>'count','base_value'=>1,'base_unit'=>(string)$product['base_unit']];
    $hay=rp_normalize(implode(' ',[(string)($site['variation_name']??''),(string)($site['attributes']??''),(string)($site['sku']??'')]));$basis=(string)$product['costing_basis'];$matches=[];
    foreach($sizes as$size){if((string)$size['measurement_type']!==$basis)continue;$needle=rp_normalize((string)$size['label']);if($needle!==''&&strpos($hay,$needle)!==false)$matches[]=$size;}
    usort($matches,fn($a,$b)=>strlen((string)$b['label'])<=>strlen((string)$a['label']));return$matches[0]??null;
}
function rp_current_prices(PDO $pdo):array{return$pdo->query("SELECT r.*,v.*,r.id retail_price_id,r.product_id,r.size_conversion_id,r.packaging_setup_id,r.woo_product_id,r.woo_variation_id,r.current_version,r.effective_date retail_effective_date FROM cw_retail_prices r JOIN cw_retail_price_versions v ON v.retail_price_id=r.id AND v.version_no=r.current_version WHERE r.active=1 ORDER BY r.id")->fetchAll();}
function rp_rows(PDO $pdo,array $sources,array $settings):array{
    $products=[];foreach($sources['products']as$p)$products[(int)$p['id']]=$p;$sizes=[];foreach($sources['sizes']as$s)$sizes[(int)$s['id']]=$s;$setups=[];foreach($sources['setups']as$s)$setups[(int)$s['id']]=$s;$website=[];foreach($sources['website']as$s)$website[(int)$s['product_id'].':'.(int)$s['variation_id']]=$s;
    $rows=[];$covered=[];$threshold=rp_num($settings['retail_low_margin_threshold']??20);
    foreach(rp_current_prices($pdo)as$price){$pid=(int)$price['product_id'];if(!isset($products[$pid]))continue;$product=$products[$pid];$size=(int)$price['size_conversion_id']===0?['id'=>0,'label'=>'1 unit','measurement_type'=>'count','base_value'=>1,'base_unit'=>$product['base_unit']]:($sizes[(int)$price['size_conversion_id']]??null);$site=$website[(int)$price['woo_product_id'].':'.(int)$price['woo_variation_id']]??null;$key=$pid.':'.(int)$price['woo_product_id'].':'.(int)$price['woo_variation_id'];$covered[$key]=true;$rows[]=rp_row($product,$size,$setups[(int)$price['packaging_setup_id']]??null,$site,$price,$threshold);}
    foreach($sources['products']as$product){$pid=(int)$product['id'];$sites=[];foreach($sources['website']as$site){$matchesVariation=(int)($product['woo_variation_id']??0)>0&&(int)$site['variation_id']===(int)$product['woo_variation_id'];$matchesProduct=(int)($product['woo_product_id']??0)>0&&(int)$site['product_id']===(int)$product['woo_product_id']&&((int)$site['variation_id']>0||(string)$site['product_type']!=='variable');$matchesSku=(string)($product['woo_sku']??'')!==''&&strcasecmp((string)$site['sku'],(string)$product['woo_sku'])===0;if($matchesVariation||$matchesProduct||$matchesSku)$sites[]=$site;}
        foreach($sites as$site){$cover=$pid.':'.(int)$site['product_id'].':'.(int)$site['variation_id'];if(isset($covered[$cover]))continue;$size=rp_match_size($site,$sources['sizes'],$product);$setup=null;if($size){foreach($sources['setups']as$candidate)if((int)$candidate['size_conversion_id']===(int)$size['id']&&rp_setup_applies($candidate,$product)){$setup=$candidate;break;}}$rows[]=rp_row($product,$size,$setup,$site,null,$threshold);$covered[$cover]=true;}
        $hasProductRow=(bool)array_filter($rows,fn($row)=>(int)$row['product_id']===$pid);if(!$hasProductRow){$added=false;foreach($sources['setups']as$setup){if(!rp_setup_applies($setup,$product)||!isset($sizes[(int)$setup['size_conversion_id']]))continue;$rows[]=rp_row($product,$sizes[(int)$setup['size_conversion_id']],$setup,null,null,$threshold);$added=true;}if(!$added)$rows[]=rp_row($product,in_array((string)$product['costing_basis'],['count','ready_made'],true)?['id'=>0,'label'=>'1 unit','measurement_type'=>'count','base_value'=>1,'base_unit'=>$product['base_unit']]:null,null,null,null,$threshold);}
    }
    usort($rows,fn($a,$b)=>strcasecmp($a['product_name'].' '.$a['size_label'],$b['product_name'].' '.$b['size_label']));return$rows;
}
function rp_row(array$product,?array$size,?array$setup,?array$site,?array$price,float$threshold):array{
    $selling=$price?rp_num($price['selling_price_inc_vat']):rp_num($site['active_price_inc_vat']??0);$vat=$price?rp_num($price['vat_rate']):15;$calc=$size?rp_calculation($product,$size,$setup,$selling,$vat):[];if($price){foreach(array_keys($calc) as $key)if(array_key_exists($key,$price))$calc[$key]=$price[$key];}$saved=$price!==null;$matched=$site!==null;$attention=!$size||!$saved||!$matched;$margin=rp_num($calc['margin_percent']??0);$status=$attention?'attention':($margin<$threshold?'low_margin':'priced');
    return array_merge($calc,['id'=>$price?(int)$price['retail_price_id']:0,'product_id'=>(int)$product['id'],'product_name'=>$product['product_name'],'short_code'=>$product['short_code'],'category'=>$product['product_category'],'basis'=>$product['costing_basis'],'base_unit'=>$product['base_unit'],'landed_cost_id'=>(int)$product['landed_cost_id'],'cost_date'=>$product['cost_date'],'size_conversion_id'=>$size?(int)$size['id']:null,'size_label'=>$size['label']??($site['variation_name']??'Size required'),'packaging_setup_id'=>$setup?(int)$setup['id']:0,'packaging_setup'=>$setup['setup_name']??'No packaging setup','woo_product_id'=>$site?(int)$site['product_id']:($price?(int)$price['woo_product_id']:0),'woo_variation_id'=>$site?(int)$site['variation_id']:($price?(int)$price['woo_variation_id']:0),'website_name'=>$site?trim((string)$site['product_name'].((string)$site['variation_name']!==''?' · '.$site['variation_name']:'')):'Not matched','website_sku'=>$site['sku']??'','website_price_inc_vat'=>$site['active_price_inc_vat']??($price['website_price_inc_vat']??null),'website_stock_quantity'=>$site['stock_quantity']??($price['website_stock_quantity']??null),'website_stock_status'=>$site['stock_status']??null,'saved'=>$saved,'matched'=>$matched,'status'=>$status,'effective_date'=>$price['retail_effective_date']??date('Y-m-d')]);
}
function rp_summary(array$rows):array{$priced=array_values(array_filter($rows,fn($r)=>$r['saved']));$margins=array_map(fn($r)=>rp_num($r['margin_percent']??0),$priced);$stockValue=0;foreach($priced as$r)$stockValue+=max(0,rp_num($r['website_stock_quantity']??0))*rp_num($r['website_price_inc_vat']??$r['selling_price_inc_vat']??0);return['rows'=>count($rows),'priced'=>count($priced),'attention'=>count(array_filter($rows,fn($r)=>$r['status']==='attention')),'average_margin'=>$margins?array_sum($margins)/count($margins):0,'stock_value'=>$stockValue];}
function rp_find(array$rows,int$id):?array{foreach($rows as$row)if((int)$row['id']===$id)return$row;return null;}

try{$pdo=db();cw_install_schema($pdo);$action=(string)($_GET['action']??'bootstrap');if($_SERVER['REQUEST_METHOD']!=='GET')cw_require_csrf();$settings=rp_settings($pdo);

 if(in_array($action,['save','preview','autosave'],true)&&$_SERVER['REQUEST_METHOD']!=='POST')rp_reply(['ok'=>false,'message'=>'Use POST for this action.'],405);
 if(in_array($action,['bootstrap','autosave'],true))rps_install($pdo);
 if($action==='bootstrap'){$sources=rpm_sources($pdo);$rows=rpm_rows($pdo,$sources,$settings);rp_reply(['ok'=>true,'rows'=>$rows,'sheet_entries'=>rps_list($pdo,$sources,$settings),'summary'=>rpm_summary($rows),'products'=>$sources['products'],'sizes'=>$sources['sizes'],'setups'=>$sources['setups'],'materials'=>$sources['materials'],'website'=>$sources['website'],'settings'=>$settings,'last_sync'=>$sources['lastSync']]);}
 if($action==='autosave'){cw_require_admin();rp_reply(rps_save($pdo,rp_body(),$settings));}
 if($action==='preview'){rp_reply(['ok'=>true,'row'=>rpm_preview(rpm_sources($pdo),$settings,rp_body())]);}
 if($action==='save'){cw_require_admin();rp_reply(rpm_save($pdo,rp_body(),$settings));}
 if($action==='history'){$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM cw_retail_price_versions WHERE retail_price_id=? ORDER BY version_no DESC');$q->execute([$id]);$versions=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM cw_retail_price_audit WHERE retail_price_id=? ORDER BY id DESC');$q->execute([$id]);rp_reply(['ok'=>true,'versions'=>$versions,'audit'=>$q->fetchAll()]);}
 if($action==='report'){$sources=rp_sources($pdo);$rows=rp_rows($pdo,$sources,$settings);$priced=array_values(array_filter($rows,fn($r)=>$r['saved']));$category=[];$inventory=['revenue'=>0.0,'cost'=>0.0,'profit'=>0.0,'stock'=>0.0];foreach($priced as$r){$stock=max(0,rp_num($r['website_stock_quantity']??0));$revenue=$stock*rp_num($r['selling_price_ex_vat']??0);$cost=$stock*rp_num($r['total_cost_ex_vat']??0);$profit=$revenue-$cost;$name=trim((string)$r['category'])?:'Uncategorised';if(!isset($category[$name]))$category[$name]=['category'=>$name,'priced_sizes'=>0,'stock'=>0.0,'revenue'=>0.0,'cost'=>0.0,'profit'=>0.0];$category[$name]['priced_sizes']++;$category[$name]['stock']+=$stock;$category[$name]['revenue']+=$revenue;$category[$name]['cost']+=$cost;$category[$name]['profit']+=$profit;$inventory['stock']+=$stock;$inventory['revenue']+=$revenue;$inventory['cost']+=$cost;$inventory['profit']+=$profit;}foreach($category as&$c)$c['margin']=$c['revenue']>0?$c['profit']/$c['revenue']*100:0;unset($c);$actual=['revenue'=>0.0,'cost'=>0.0,'profit'=>0.0,'quantity'=>0.0,'matched_lines'=>0,'unmatched_lines'=>0];$salesBy=[];$salesAvailable=rp_table_exists($pdo,'woo_sales');if($salesAvailable){$year=(int)($_GET['year']??date('Y'));$month=max(1,min(12,(int)($_GET['month']??date('n'))));$from=sprintf('%04d-%02d-01',$year,$month);$to=(new DateTimeImmutable($from))->modify('+1 month')->format('Y-m-d');$st=$pdo->prepare('SELECT woo_product_id,COALESCE(woo_variation_id,0) woo_variation_id,product_name,SUM(quantity) quantity,SUM(line_total) revenue_ex_vat FROM woo_sales WHERE sold_at>=? AND sold_at<? GROUP BY woo_product_id,COALESCE(woo_variation_id,0),product_name ORDER BY revenue_ex_vat DESC');$st->execute([$from,$to]);$priceMap=[];foreach($priced as$r){$key=(int)$r['woo_product_id'].':'.(int)$r['woo_variation_id'];if((int)$r['woo_product_id']>0)$priceMap[$key]=$r;}foreach($st->fetchAll()as$s){$key=(int)$s['woo_product_id'].':'.(int)$s['woo_variation_id'];$r=$priceMap[$key]??$priceMap[(int)$s['woo_product_id'].':0']??null;$qty=rp_num($s['quantity']);$revenue=rp_num($s['revenue_ex_vat']);$cost=$r?$qty*rp_num($r['total_cost_ex_vat']):0;$profit=$revenue-$cost;$matched=$r!==null;$actual['revenue']+=$revenue;$actual['quantity']+=$qty;if($matched){$actual['cost']+=$cost;$actual['profit']+=$profit;$actual['matched_lines']++;}else$actual['unmatched_lines']++;$salesBy[]=['product'=>$s['product_name'].((int)$s['woo_variation_id']>0?' · variation '.(int)$s['woo_variation_id']:''),'quantity'=>$qty,'revenue'=>$revenue,'cost'=>$matched?$cost:null,'profit'=>$matched?$profit:null,'margin'=>$matched&&$revenue>0?$profit/$revenue*100:null,'matched'=>$matched];}}$summary=['actual_revenue'=>$actual['revenue'],'actual_profit'=>$actual['profit'],'actual_margin'=>$actual['revenue']>0?$actual['profit']/$actual['revenue']*100:0,'inventory_revenue'=>$inventory['revenue'],'inventory_profit'=>$inventory['profit'],'weighted_margin'=>$inventory['revenue']>0?$inventory['profit']/$inventory['revenue']*100:0];rp_reply(['ok'=>true,'summary'=>$summary,'inventory'=>$inventory,'actual'=>$actual,'categories'=>array_values($category),'sales'=>$salesBy,'coverage'=>['pricing_rows'=>count($rows),'priced_rows'=>count($priced),'website_matched'=>count(array_filter($priced,fn($r)=>$r['matched'])),'sales_available'=>$salesAvailable,'last_sync'=>$sources['lastSync']]]);}
 throw new RuntimeException('Unsupported action.');
}catch(Throwable$e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Retail pricing: '.get_class($e));rp_reply(['ok'=>false,'message'=>$e->getMessage()],400);}
